// Cubes each element of the input vector and returns a new vector of the same length.
//
// This is total and terminating for all inputs: it performs a single pass over `a`
// and allocates an output vector of identical length.
pub fn cube_elements(a: Vec<i128>) -> Vec<i128> {
    a.into_iter().map(|x| x * x * x).collect()
}

